type SensitiveField = 'ssn' | 'dateOfBirth' | 'annualIncome';
type NonSensitiveField = Exclude<FieldName, SensitiveField>;

interface FieldError {
  field: FieldName;
  code: string;
  message: string;
}

type SubmitReply =
  | { kind: 'created'; applicationId: string; status: DecisionStatus }
  | { kind: 'replayed'; applicationId: string; status: DecisionStatus }
  | { kind: 'field-errors'; errors: FieldError[] };

interface ApplicationGateway {
  submit(
    fields: Record<FieldName, string>,
    idempotencyKey: string,
    signal: AbortSignal,
  ): Promise<SubmitReply>;
  status(applicationId: string): Promise<ApplicationRecord>;
  saveDraft(draftId: string, fields: Partial<Record<NonSensitiveField, string>>): Promise<void>;
}

type TelemetryEvent =
  | { name: 'section_viewed'; section: SectionId }
  | { name: 'field_error'; section: SectionId; field: FieldName; code: string }
  | { name: 'submit_sent'; attempt: number }
  | { name: 'outcome_shown'; status: DecisionStatus | 'failed'; elapsedMs: number };

interface Telemetry {
  track(event: TelemetryEvent): void;
}
